use crate::model::ModelError;

/// A sound for a step boundary: one of the short sounds the app ships
/// (`assets/sounds/<id>.mp3`, generated by `scripts/gen-sounds.py`), a
/// single cue of 1 s so it never outlasts a short step. A closed set.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum StepSound {
    TempleBlock,
    WoodenClappers,
    Tingsha,
    WaterDrop,
    Kalimba,
    BreathAndBowl,
    BambooTock,
}

impl StepSound {
    /// Every step sound, in the picker's order.
    pub const ALL: [Self; 7] = [
        Self::TempleBlock,
        Self::WoodenClappers,
        Self::Tingsha,
        Self::WaterDrop,
        Self::Kalimba,
        Self::BreathAndBowl,
        Self::BambooTock,
    ];

    /// Before one is chosen: the one every step played before the choice
    /// existed, so an update changes nothing.
    pub const DEFAULT: Self = Self::BreathAndBowl;

    /// The id: the asset's file stem and the string persisted in storage.
    pub fn id(self) -> &'static str {
        match self {
            Self::TempleBlock => "temple-block",
            Self::WoodenClappers => "wooden-clappers",
            Self::Tingsha => "tingsha",
            Self::WaterDrop => "water-drop",
            Self::Kalimba => "kalimba",
            Self::BreathAndBowl => "breath-and-bowl",
            Self::BambooTock => "bamboo-tock",
        }
    }

    /// The picker's name: `Temple block`.
    pub fn label(self) -> &'static str {
        match self {
            Self::TempleBlock => "Temple block",
            Self::WoodenClappers => "Wooden clappers",
            Self::Tingsha => "Tingsha",
            Self::WaterDrop => "Water drop",
            Self::Kalimba => "Kalimba",
            Self::BreathAndBowl => "Breath and bowl",
            Self::BambooTock => "Bamboo tock",
        }
    }

    /// How long the asset plays, in ms: every step sound is 1 s.
    pub fn duration_ms(self) -> u32 {
        1000
    }

    /// Parses a [`StepSound::id`] strictly: anything else, an end-of-brew
    /// sound included, is [`ModelError::UnknownStepSound`].
    pub fn try_parse(raw: &str) -> Result<Self, ModelError> {
        Self::ALL
            .into_iter()
            .find(|sound| sound.id() == raw)
            .ok_or_else(|| ModelError::UnknownStepSound(raw.to_owned()))
    }
}
